let data = msg.payload;

return [
    { payload: parseFloat(data.confidence) }, // 1 -> gauge
    { payload: data.checks[0] },             // 2 -> STAT box
    { payload: data.ai_prediction }          // 3 -> AI box
];

let d;
try {
    d = JSON.parse(msg.payload);
} catch (e) {
    node.warn("invalid JSON from ESP32: " + msg.payload);
    return null;
}

return [
    { payload: d.current },
    { payload: d.temperature },
    { payload: d.vibration }
];

// تجهيز البيانات لإرسالها إلى موديل الـ Machine Learning

msg.payload = JSON.stringify({
    current: Number(msg.payload.current_A),
    temperature: Number(msg.payload.temp_C),
    vibration: Number(msg.payload.vibration)
}) + "\n";

return msg;

if (typeof msg.payload === "string") {
    msg.payload = JSON.parse(msg.payload);
}

let data = msg.payload;

msg.payload = {
    current: Number(data.current),
    temperature: Number(data.temperature),
    vibration: Number(data.vibration),
    mlState: data.ai_prediction,
    confidence: Number(data.confidence)
};

return msg;
node.warn(data);

msg.payload = {
    current: Number(data.current),
    temperature: Number(data.temperature),
    vibration: Number(data.vibration),
    mlState: data.ai_prediction,
    confidence: Number(data.confidence)
};

return msg;

let data = msg.payload;

return [
    { payload: parseFloat(data.confidence) }, // 1
    { payload: data.checks[0] },             // 2
    { payload: data.ai_prediction }          // 3
];

// حفظ القراءة الحالية في الذاكرة
if (msg.topic) {
    flow.set("sensor_" + msg.topic, msg.payload);
}

// استدعاء آخر قيم متسجلة
var t   = flow.get("sensor_t")   || 0;
var v   = flow.get("sensor_v")   || 0;
var c   = flow.get("sensor_c")   || 0;
var vol = flow.get("sensor_vol") || 0;

// تجميعهم في أوبجكت واحد بيبعت فوراً بدون تأخير
msg.payload = {
    t: Number(t),
    v: Number(v),
    c: Number(c),
    vol: Number(vol)
};

return msg;

let state = flow.get('state') || {
    main_switch: false,
    contactor: false,
    overload_tripped: false,
    motor_enabled: false,
    simulate_overcurrent: false
};

if (msg.topic && state.hasOwnProperty(msg.topic)) {
    state[msg.topic] = msg.payload;
}
flow.set('state', state);

const v_source = true;
const v_switch = state.main_switch;
const v_contactor = v_switch && state.contactor;
const v_overload = v_contactor && !state.overload_tripped;
const v_motor = v_overload;

let current = 0;
if (v_motor && state.motor_enabled) {
    current = state.simulate_overcurrent ? (14 + Math.random() * 2) : (2.3 + Math.random() * 0.4);
}
current = Number(current.toFixed(2));

const overcurrent = current >= 10;
const motor_running = current > 0.5 && !overcurrent;

let temperature = 25;
if (motor_running) temperature = 45 + Math.random() * 10;
if (overcurrent) temperature = 80 + Math.random() * 15;
temperature = Number(temperature.toFixed(1));

let vibration = motor_running ? Number((0.8 + Math.random() * 0.4).toFixed(2)) : Number((0.05 + Math.random() * 0.05).toFixed(2));
if (overcurrent) vibration = Number((2.5 + Math.random() * 1.5).toFixed(2));

let diagnostics = [];
let severity = 'ok';

if (state.overload_tripped) {
    diagnostics = ['Overload relay has tripped.'];
    severity = 'fault';
} else if (v_switch && !state.contactor) {
    diagnostics = ['Contactor not energized or contacts failed.'];
    severity = 'warning';
} else if (overcurrent) {
    diagnostics = [
        'Overcurrent detected.',
        'Possible causes: mechanical jam, bearing failure, locked rotor.'
    ];
    severity = 'fault';
} else if (v_motor && state.motor_enabled && current === 0) {
    diagnostics = [
        'Power reaches motor but no current detected.',
        'Possible causes: open winding, broken cable, disconnected terminal, tripped overload.'
    ];
    severity = 'fault';
} else if (!v_switch) {
    diagnostics = ['Main switch is open. No power in circuit.'];
    severity = 'info';
} else {
    diagnostics = ['System operating normally.'];
    severity = 'ok';
}

let compVoltage = {
    source: v_source,
    switch: v_switch,
    contactor: v_contactor,
    overload: v_overload,
    motor: v_motor
};

let compTimes = flow.get('compTimes') || {};
let prevVoltage = flow.get('prevVoltage') || {};
let log = flow.get('log') || [];
const now = new Date().toLocaleTimeString();

Object.keys(compVoltage).forEach(k => {
    if (prevVoltage[k] === undefined) prevVoltage[k] = compVoltage[k];
    if (prevVoltage[k] !== compVoltage[k]) {
        compTimes[k] = now;
        log.unshift(now + ' - ' + k + ' voltage ' + (compVoltage[k] ? 'ON' : 'OFF'));
        if (log.length > 10) log = log.slice(0, 10);
        prevVoltage[k] = compVoltage[k];
    }
});
flow.set('compTimes', compTimes);
flow.set('prevVoltage', prevVoltage);
flow.set('log', log);

const components = {
    source: { voltage: v_source, current: v_source ? current : 0, lastChange: compTimes.source || '-', fault: 'None' },
    switch: { voltage: v_switch, current: v_switch ? current : 0, lastChange: compTimes.switch || '-', fault: !v_switch ? 'Main switch open' : 'None' },
    contactor: { voltage: v_contactor, current: v_contactor ? current : 0, lastChange: compTimes.contactor || '-', fault: (v_switch && !v_contactor) ? 'Contactor not energized' : 'None' },
    overload: { voltage: v_overload, current: v_overload ? current : 0, lastChange: compTimes.overload || '-', fault: state.overload_tripped ? 'Overload tripped' : 'None' },
    motor: { voltage: v_motor, current: current, lastChange: compTimes.motor || '-', fault: overcurrent ? 'Overcurrent' : ((v_motor && state.motor_enabled && current === 0) ? 'No current - check winding/cable' : 'None') }
};

msg.payload = {
    v_source, v_switch, v_contactor, v_overload, v_motor,
    current,
    temperature,
    vibration,
    motor_running,
    overcurrent,
    motor_fault: severity === 'fault',
    diagnostics,
    severity,
    state,
    components,
    log
};

return msg;

// ============================================================
// FaultZero - Voltage Propagation State Engine
// Persists component state in flow context and recomputes the
// live electrical state of every wire segment on each change.
// ============================================================
let state = flow.get('componentStates') || {
    main_power: false,
    mcb_closed: false,
    fuse_ok: false,
    estop_ok: false,
    plc_run: false,
    km1_cmd: false,
    aux_contact_ok: false,
    overload_ok: false,
    overcurrent_sim: false,
    km2_cmd: false,
    aux_contact_ok_2: false,
    overload_ok_2: false
};

if (msg.topic && state.hasOwnProperty(msg.topic)) {
    state[msg.topic] = msg.payload;
}
flow.set('componentStates', state);

// --- Voltage propagation (single-line representation of 3-phase trunk) ---
const seg = {};

seg.L1 = true;
seg.L2 = true;
seg.L3 = true;

seg.mcb_in  = seg.L1;
seg.mcb_out = seg.mcb_in && state.main_power && state.mcb_closed;

seg.fuse_in  = seg.mcb_out;
seg.fuse_out = seg.fuse_in && state.fuse_ok;

seg.estop_line    = seg.fuse_out && state.estop_ok;
seg.control_power = seg.estop_line && state.plc_run;

seg.contactor_coil = seg.control_power && state.km1_cmd;
seg.contactor_in    = seg.fuse_out;
seg.contactor_out   = seg.contactor_in && seg.contactor_coil;

seg.aux_contact = seg.contactor_coil && state.aux_contact_ok;

seg.overload_in  = seg.contactor_out;
seg.overload_out = seg.overload_in && state.overload_ok;

seg.motor_in      = seg.overload_out;
seg.motor_running = seg.motor_in && !state.overcurrent_sim;

// --- Motor 2 (Freezer Conveyor) own circuit ---
// Shares the common bus (fuse_out / estop_line / control_power) with Motor 1,
// but has its OWN contactor / overload / motor state.
const seg2 = {};
seg2.contactor_coil = seg.control_power && state.km2_cmd;
seg2.contactor_in    = seg.fuse_out;
seg2.contactor_out   = seg2.contactor_in && seg2.contactor_coil;
seg2.aux_contact = seg2.contactor_coil && state.aux_contact_ok_2;
seg2.overload_in  = seg2.contactor_out;
seg2.overload_out = seg2.overload_in && state.overload_ok_2;
seg2.motor_in      = seg2.overload_out;
seg2.motor_running = seg2.motor_in;

// --- PLC I/O mapping (S7-1200 simulated addresses) ---
const plc = {
    I0_0: state.estop_ok,
    I0_1: seg.aux_contact,
    I0_2: state.overload_ok,
    I0_3: seg2.aux_contact,
    I0_4: state.overload_ok_2,
    I0_5: false,
    Q0_0: seg.contactor_coil,
    Q0_1: state.overcurrent_sim,
    Q0_2: seg.motor_running,
    Q0_3: seg2.contactor_coil,
    Q0_4: false,
    Q0_5: seg2.motor_running
};

msg.payload = {
    componentStates: state,
    segments: seg,
    segments2: seg2,
    plc: plc,
    ts: Date.now()
};

return msg;

// ============================================================
// FaultZero - Diagnostic Engine
// Consumes the propagated state and emits an ordered fault list.
// ============================================================
const s = msg.payload.componentStates;
const seg = msg.payload.segments;
const faults = [];

if (!s.main_power) {
    faults.push({code:'NO_MAIN_POWER', ar:'لا يوجد تغذية رئيسية', en:'Main power OFF', severity:'critical', component:'main_power'});
} else if (!s.mcb_closed) {
    faults.push({code:'MCB_TRIP', ar:'القاطع الرئيسي مفصول', en:'MCB tripped / open', severity:'critical', component:'mcb'});
} else if (!s.fuse_ok) {
    faults.push({code:'FUSE_OPEN', ar:'الفيوز مفتوح', en:'Fuse open / blown', severity:'critical', component:'fuse'});
} else if (!s.estop_ok) {
    faults.push({code:'ESTOP_ACTIVE', ar:'زر الطوارئ مضغوط', en:'Emergency stop active', severity:'critical', component:'estop'});
} else if (!s.plc_run) {
    faults.push({code:'PLC_STOP', ar:'الـPLC في وضع STOP', en:'PLC in STOP mode', severity:'warning', component:'plc'});
}

if (seg.control_power && s.km1_cmd && !seg.contactor_coil) {
    faults.push({code:'CONTACTOR_COIL_OPEN', ar:'ملف الكونتاكتور KM1 مفتوح', en:'Contactor coil circuit open', severity:'critical', component:'km1'});
}
if (seg.contactor_coil && !s.aux_contact_ok) {
    faults.push({code:'AUX_CONTACT_FAULT', ar:'عطل في نقطة التغذية الراجعة KM1', en:'Auxiliary contact fault', severity:'warning', component:'km1'});
}
if (seg.overload_in && !s.overload_ok) {
    faults.push({code:'OVERLOAD_TRIP', ar:'مرحل الحمل الزائد فصل', en:'Overload relay tripped', severity:'critical', component:'overload'});
}
if (seg.motor_in && s.overcurrent_sim) {
    faults.push({code:'MOTOR_OVERCURRENT', ar:'تيار زائد بالموتور', en:'Motor overcurrent detected', severity:'critical', component:'motor'});
}
if (seg.contactor_out && !seg.motor_running && !s.overcurrent_sim) {
    faults.push({code:'MOTOR_NO_CURRENT', ar:'لا يوجد تيار بالموتور رغم التغذية', en:'Motor no current despite supply present', severity:'warning', component:'motor'});
}

// --- Motor 2 (Freezer Conveyor) diagnostics ---
const s2 = msg.payload.segments2;
if (seg.control_power && s.km2_cmd && !s2.contactor_coil) {
    faults.push({code:'M2_CONTACTOR_COIL_OPEN', ar:'ملف الكونتاكتور KM2 مفتوح', en:'KM2 contactor coil circuit open', severity:'critical', component:'km2'});
}
if (s2.contactor_coil && !s.aux_contact_ok_2) {
    faults.push({code:'M2_AUX_CONTACT_FAULT', ar:'عطل في نقطة التغذية الراجعة KM2', en:'KM2 auxiliary contact fault', severity:'warning', component:'km2'});
}
if (s2.overload_in && !s.overload_ok_2) {
    faults.push({code:'M2_OVERLOAD_TRIP', ar:'مرحل الحمل الزائد FR2 فصل', en:'FR2 overload relay tripped', severity:'critical', component:'overload2'});
}
if (s2.contactor_out && !s2.motor_running) {
    faults.push({code:'M2_MOTOR_NO_CURRENT', ar:'لا يوجد تيار بموتور الفريزر رغم التغذية', en:'Motor 2 no current despite supply present', severity:'warning', component:'motor2'});
}

if (faults.length === 0) {
    faults.push({code:'SYSTEM_OK', ar:'النظام يعمل بشكل طبيعي', en:'System healthy', severity:'ok', component:'system'});
}

msg.payload.diagnostics = faults;
return msg;

// ============================================================
// استقبال إما من PLC (s7 in) أو من HMI (ui_template)
// ============================================================

// ---- 1. تحميل البيانات المخزنة من PLC ----
let plcData = global.get('plcData') || {};

// ---- 2. إذا كانت الرسالة من PLC (تحتوي على topic وقيمة boolean) ----
if (msg.topic && typeof msg.payload === 'boolean') {
    // تحديث القيمة في الكائن المخزن
    plcData[msg.topic] = msg.payload;
    global.set('plcData', plcData);

    // بناء رسالة التحديث للـ UI
    return buildUIMessage(plcData);
}

// ---- 3. إذا كانت الرسالة أمر من HMI (payload.command و payload.target) ----
//    (نحتفظ بالمنطق القديم لكن ممكن نعدله عشان يبعت أوامر لـ PLC via s7 out)
const cmd = msg.payload?.command;
const target = msg.payload?.target;

if (cmd && target) {
    let state = global.get('motorStates') || {
        m1: false, m2: false, m3: false, m4: false,
        seqRunning: false, plcRun: true
    };

    if (target === 'system' && cmd === 'reset') {
        state.m1 = false; state.m2 = false; state.m3 = false; state.m4 = false;
        state.seqRunning = false; state.plcRun = true;
    } else if (target === 'seq') {
        state.seqRunning = (cmd === 'start');
    } else {
        const motorMap = { m1: 'm1', m2: 'm2', m3: 'm3', m4: 'm4' };
        if (motorMap[target]) {
            if (cmd === 'start') state[motorMap[target]] = true;
            else if (cmd === 'stop') state[motorMap[target]] = false;
        }
    }
    global.set('motorStates', state);

    // هنا ممكن ترسل الأمر إلى PLC عبر s7 out، لكن مش موجود حالياً
    // نعيد بناء الرسالة من plcData (مع دمج state لو احتاج)
    return buildUIMessage(plcData);
}

// ---- 4. لو الرسالة مش معروفة، نرجعها كما هي أو نرجع رسالة افتراضية ----
return buildUIMessage(plcData);

// ============================================================
// دالة مساعدة لبناء الرسالة بالشكل المطلوب للـ ui_template
// ============================================================
function buildUIMessage(data) {
    // القيم الافتراضية في حالة عدم وجود بيانات
    const def = (key, fallback) => (data[key] !== undefined ? data[key] : fallback);

    // ---- استخراج القيم من بيانات PLC ----
    const mainPower   = def('Main Power', false);
    const mcb         = def('MCB (Main Breaker)', false);
    const plcRun      = def('PLC RUN', true);
    const estop       = def('E-Stop Released', false);
    const fuse        = def('Fuse', false);

    // M1
    const m1_start    = def('M1 START (SB3)', false);
    const m1_aux      = def('M1 Aux OK', false);
    const m1_fr       = def('M1 FR OK', false);
    // M2
    const m2_cmd      = def('M2 KM Cmd (PLC Q1)', false);
    const m2_aux      = def('M2 KM Aux OK (I3)', false);
    const m2_fr       = def('M2 FR OK (I4)', false);
    // M3
    const m3_start    = def('M3 START (SB5)', false);
    const m3_aux      = def('M3 Aux OK', false);
    const m3_fr       = def('M3 FR OK', false);
    // M4
    const m4_run      = def('M4 VFD Run (PLC Q2)', false);
    const m4_fault    = def('M4 VFD Fault', false);

    // ---- حساب الحالات المنطقية لكل موتور (محاكاة بسيطة) ----
    // يمكنك تعديل المنطق حسب تصميم PLC الفعلي
    const safety = mainPower && mcb && estop && fuse && plcRun;

    // M1
    const m1_contactor_in = safety && m1_start && m1_fr && m1_aux;
    const m1_running      = m1_contactor_in;
    const m1_tripped      = !m1_fr && m1_contactor_in;

    // M2
    const m2_contactor_in = safety && m2_cmd && m2_fr && m2_aux;
    const m2_running      = m2_contactor_in;
    const m2_tripped      = !m2_fr && m2_contactor_in;

    // M3
    const m3_contactor_in = safety && m3_start && m3_fr && m3_aux;
    const m3_running      = m3_contactor_in;
    const m3_tripped      = !m3_fr && m3_contactor_in;

    // M4 (VFD)
    const m4_vfd_enabled  = safety && m4_run && !m4_fault;
    const m4_running      = m4_vfd_enabled;
    const m4_tripped      = m4_fault;

    // ---- بناء الرسالة النهائية ----
    return {
        payload: {
            system: {
                main_power: mainPower,
                mcb: mcb,
                plc_run: plcRun
            },
            io: {
                sq1: false,        // غير مستخدمة من PLC حالياً
                sb7: false,
                sq2: false,
                sq3: false,
                sa1_pos1: false,
                sa1_pos2: false,
                sa1_pos3: false,
                sq4: false,
                sq5_sq6: false,
                sb8: false
            },
            motors: {
                m1: {
                    contactor_in: m1_contactor_in,
                    coil_energized: m1_contactor_in,
                    contactor_out: m1_contactor_in,
                    fr_ok: m1_fr,
                    tripped: m1_tripped,
                    running: m1_running,
                    km_command: m1_start,
                    km_aux_ok: m1_aux,
                    diagnostics: m1_tripped ? [{ en: 'Overload tripped (FR1)' }] : []
                },
                m2: {
                    contactor_in: m2_contactor_in,
                    coil_energized: m2_contactor_in,
                    contactor_out: m2_contactor_in,
                    fr_ok: m2_fr,
                    tripped: m2_tripped,
                    running: m2_running,
                    km_command: m2_cmd,
                    km_aux_ok: m2_aux,
                    diagnostics: m2_tripped ? [{ en: 'Overload tripped (FR2)' }] : []
                },
                m3: {
                    contactor_in: m3_contactor_in,
                    coil_energized: m3_contactor_in,
                    contactor_out: m3_contactor_in,
                    fr_ok: m3_fr,
                    tripped: m3_tripped,
                    running: m3_running,
                    km_command: m3_start,
                    km_aux_ok: m3_aux,
                    diagnostics: m3_tripped ? [{ en: 'Overload tripped (FR3)' }] : []
                },
                m4: {
                    power_in: m4_vfd_enabled,
                    vfd_enabled: m4_vfd_enabled,
                    vfd_run: m4_run,
                    running: m4_running,
                    diagnostics: m4_fault ? [{ en: 'VFD Fault' }] : []
                }
            },
            sequence: {
                step0: mainPower && mcb && estop && fuse,
                step1: mainPower && mcb && estop && fuse && plcRun,
                step2: mainPower && mcb && estop && fuse && plcRun && m1_running && m3_running,
                step3: mainPower && mcb && estop && fuse && plcRun && m1_running && m3_running && m2_running,
                step4: mainPower && mcb && estop && fuse && plcRun && m1_running && m3_running && m2_running && m4_running
            }
        }
    };
}
